#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<pair<long long, long long>> requests(n);
    for (auto &r : requests) scanf("%lld %lld", &r.first, &r.second);
    sort(requests.begin(), requests.end());
    // busy: (return time, car) min-heap; free: smallest idle car id first.
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> busy;
    priority_queue<int, vector<int>, greater<>> freeCars;
    vector<vector<pair<long long, long long>>> cars;
    for (auto [p, r] : requests) {
        while (!busy.empty() && busy.top().first <= p) { freeCars.push(busy.top().second); busy.pop(); }
        int car;
        if (!freeCars.empty()) { car = freeCars.top(); freeCars.pop(); }
        else { car = cars.size(); cars.emplace_back(); }
        cars[car].push_back({p, r});
        busy.push({r, car});
    }
    string out = to_string(cars.size()) + "\n";
    for (size_t i = 0; i < cars.size(); i++) {
        out += to_string(i) + ":";
        for (auto [p, r] : cars[i]) out += " (" + to_string(p) + "," + to_string(r) + ")";
        out += "\n";
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[][] requests = new long[n][2];
        for (int i = 0; i < n; i++) {
            st.nextToken(); requests[i][0] = (long) st.nval;
            st.nextToken(); requests[i][1] = (long) st.nval;
        }
        Arrays.sort(requests, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        // busy: {return time, car} min-heap; free: smallest idle car id first.
        PriorityQueue<long[]> busy = new PriorityQueue<>((x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        PriorityQueue<Integer> free = new PriorityQueue<>();
        List<List<long[]>> cars = new ArrayList<>();
        for (long[] req : requests) {
            while (!busy.isEmpty() && busy.peek()[0] <= req[0]) free.add((int) busy.poll()[1]);
            int car;
            if (!free.isEmpty()) car = free.poll();
            else { car = cars.size(); cars.add(new ArrayList<>()); }
            cars.get(car).add(req);
            busy.add(new long[] {req[1], car});
        }
        StringBuilder sb = new StringBuilder();
        sb.append(cars.size()).append('\n');
        for (int i = 0; i < cars.size(); i++) {
            sb.append(i).append(':');
            for (long[] r : cars.get(i)) sb.append(" (").append(r[0]).append(',').append(r[1]).append(')');
            sb.append('\n');
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        pw.print(sb);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"container/heap"
	"os"
	"sort"
	"strconv"
)

// busyHeap orders (return time, car) pairs; intHeap yields the smallest idle car id.
type busyHeap [][2]int

func (h busyHeap) Len() int { return len(h) }
func (h busyHeap) Less(i, j int) bool {
	if h[i][0] != h[j][0] {
		return h[i][0] < h[j][0]
	}
	return h[i][1] < h[j][1]
}
func (h busyHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *busyHeap) Push(x any)   { *h = append(*h, x.([2]int)) }
func (h *busyHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	requests := make([][2]int, n)
	for i := range requests {
		requests[i] = [2]int{nextInt(), nextInt()}
	}
	sort.Slice(requests, func(i, j int) bool {
		if requests[i][0] != requests[j][0] {
			return requests[i][0] < requests[j][0]
		}
		return requests[i][1] < requests[j][1]
	})
	busy := &busyHeap{}
	free := &intHeap{}
	var cars [][][2]int
	for _, req := range requests {
		for busy.Len() > 0 && (*busy)[0][0] <= req[0] {
			heap.Push(free, heap.Pop(busy).([2]int)[1])
		}
		var car int
		if free.Len() > 0 {
			car = heap.Pop(free).(int)
		} else {
			car = len(cars)
			cars = append(cars, nil)
		}
		cars[car] = append(cars[car], req)
		heap.Push(busy, [2]int{req[1], car})
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	out.WriteString(strconv.Itoa(len(cars)) + "\n")
	for i, list := range cars {
		out.WriteString(strconv.Itoa(i) + ":")
		for _, r := range list {
			out.WriteString(" (" + strconv.Itoa(r[0]) + "," + strconv.Itoa(r[1]) + ")")
		}
		out.WriteByte('\n')
	}
}
